CREATE OR REPLACE FUNCTION public.booking_notification_attempt_state_valid()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d booking_notification_deliveries%ROWTYPE; a booking_notification_attempts%ROWTYPE; target uuid;
BEGIN
 IF TG_TABLE_NAME='booking_notification_deliveries' THEN target=NEW.id;
 ELSIF TG_TABLE_NAME='booking_notification_attempts' THEN target=NEW.delivery_id;
 ELSE SELECT delivery_id INTO target FROM booking_notification_attempts WHERE id=NEW.attempt_id; END IF;
 SELECT * INTO d FROM booking_notification_deliveries WHERE id=target FOR UPDATE;
 IF d.attempt_count<>(SELECT count(*) FROM booking_notification_attempts WHERE delivery_id=target)
 THEN RAISE EXCEPTION 'booking_notification_attempt_count_invalid'; END IF;
 IF d.attempt_count>0 THEN
  SELECT * INTO a FROM booking_notification_attempts WHERE delivery_id=target AND ordinal=d.attempt_count;
  IF NOT FOUND OR a.bot_key IS DISTINCT FROM d.bot_key OR
    (d.external_chat_id IS NOT NULL AND a.chat_id IS DISTINCT FROM d.external_chat_id)
  THEN RAISE EXCEPTION 'booking_notification_attempt_binding_invalid'; END IF;
 END IF;
 IF d.state='sending' AND (a.id IS NULL OR a.claim_token IS DISTINCT FROM d.lease_token OR EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id))
 THEN RAISE EXCEPTION 'booking_notification_sending_invalid'; END IF;
 IF d.state='delivered' AND NOT EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id AND outcome='applied')
 THEN RAISE EXCEPTION 'booking_notification_receipt_required'; END IF;
 IF d.state IN ('unknown','manual') AND NOT EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id AND outcome='unknown')
 THEN RAISE EXCEPTION 'booking_notification_uncertainty_required'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.clear_expert_offer_delivery_state(subject uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF subject IS NULL THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(subject::text,0));
 UPDATE expert_personal_offer_state SET payment_id=NULL,payment_url=NULL WHERE user_id=subject;
 UPDATE expert_personal_offer_notices SET status=CASE WHEN status IN('pending','unknown_outcome') THEN 'cancelled' ELSE status END,receipt=NULL WHERE user_id=subject;
 UPDATE expert_offer_schedules SET bot_id=NULL,bot_key=NULL,chat_id=NULL WHERE user_id=subject;
END $function$

CREATE OR REPLACE FUNCTION public.client_booking_guard_privacy_completion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IN ('processor_complete','backup_verified')
     AND EXISTS (
       SELECT 1 FROM client_booking_erasure_work w
       WHERE w.deletion_job_id=NEW.id AND w.phase <> 'complete'
     ) THEN
    RAISE EXCEPTION 'client_booking_erasure_incomplete' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_ledger_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  package_row "message_packages"%ROWTYPE;
  original_grant "message_ledger_entries"%ROWTYPE;
BEGIN
  IF NEW.legacy_admin_fact THEN
    RAISE EXCEPTION 'legacy admin ledger marker is migration-only' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO package_row
  FROM "message_packages"
  WHERE "id" = NEW."package_id";
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF package_row."kind" = 'paid' THEN
    IF NEW."admin_approval_id" IS NOT NULL OR NEW."admin_requester_session_id_hash" IS NOT NULL THEN
      RAISE EXCEPTION 'paid ledger facts cannot carry admin approval provenance' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF package_row."legacy_admin_grant" THEN
    IF NEW."entry_kind" IN ('grant', 'revocation') THEN
      RAISE EXCEPTION 'legacy admin entitlements cannot receive new admin grant or revocation facts' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW."entry_kind" = 'grant' AND (
    NEW."admin_approval_id" IS DISTINCT FROM package_row."admin_approval_id"
    OR NEW."admin_requester_session_id_hash" IS DISTINCT FROM package_row."admin_requester_session_id_hash"
  ) THEN
    RAISE EXCEPTION 'admin grant provenance must match package provenance' USING ERRCODE = '23514';
  END IF;
  IF NEW."entry_kind" = 'revocation' THEN
    IF NEW."admin_approval_id" IS NULL OR NEW."admin_requester_session_id_hash" IS NULL THEN
      RAISE EXCEPTION 'admin revocation provenance is required' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO original_grant
    FROM "message_ledger_entries"
    WHERE "id" = NEW."original_entry_id"
      AND "package_id" = NEW."package_id"
      AND "entry_kind" = 'grant';
    IF NOT FOUND
      OR original_grant."admin_approval_id" IS DISTINCT FROM package_row."admin_approval_id"
      OR original_grant."admin_requester_session_id_hash" IS DISTINCT FROM package_row."admin_requester_session_id_hash"
    THEN
      RAISE EXCEPTION 'admin revocation original grant provenance is invalid' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM "admin_approvals" a
      WHERE a."id" = NEW."admin_approval_id"
        AND a."requester_session_id_hash" = NEW."admin_requester_session_id_hash"
        AND a."action" = 'package.revoke'
        AND a."object_type" = 'user'
        AND a."object_id" = package_row."user_id"
        AND a."required_role" = 'entitlement_admin'
        AND a."payload_hash" = 'sha256:' || encode(digest(convert_to(
          '{"idempotencyKey":' || to_json(NEW."idempotency_key")::text ||
          ',"packageId":' || to_json(NEW."package_id"::text)::text ||
          ',"userId":' || to_json(package_row."user_id"::text)::text || '}',
          'UTF8'
        ), 'sha256'), 'hex')
        AND a."consumed_at" IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'admin revocation approval provenance is invalid' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_package_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  expected_action text;
  expected_payload_hash text;
BEGIN
  IF NEW.legacy_admin_grant THEN
    RAISE EXCEPTION 'legacy admin package marker is migration-only' USING ERRCODE = '23514';
  END IF;
  IF NEW.kind = 'paid' THEN
    RETURN NEW;
  END IF;
  expected_action := CASE WHEN NEW.kind = 'admin' THEN 'package.grant' ELSE 'package.intro_grant' END;
  expected_payload_hash := 'sha256:' || encode(digest(convert_to(
    '{"idempotencyKey":' || to_json(NEW.grant_idempotency_key)::text ||
    ',"units":' || NEW.granted_messages::text ||
    ',"userId":' || to_json(NEW.user_id::text)::text || '}',
    'UTF8'
  ), 'sha256'), 'hex');
  IF NOT EXISTS (
    SELECT 1
    FROM "admin_approvals" a
    WHERE a."id" = NEW."admin_approval_id"
      AND a."requester_session_id_hash" = NEW."admin_requester_session_id_hash"
      AND a."action" = expected_action
      AND a."object_type" = 'user'
      AND a."object_id" = NEW."user_id"
      AND a."required_role" = 'entitlement_admin'
      AND a."payload_hash" = expected_payload_hash
      AND a."consumed_at" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'admin package approval provenance is invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_client_coupon_purchase()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM client_paid_orders o WHERE o.id = NEW.order_id
    AND o.mode = 'live' AND o.user_id = NEW.user_id AND o.coupon_grant_minor = NEW.amount_minor
    AND NEW.captured_at >= o.created_at) THEN
    RAISE EXCEPTION 'client coupon purchase mismatch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_expert_application_identity_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.campaign_quote_id IS DISTINCT FROM OLD.campaign_quote_id THEN
    RAISE EXCEPTION 'expert_application_identity_immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_application_promo_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM expert_onboarding_applications a JOIN expert_onboarding_invoices i ON i.application_id=a.id AND i.user_id=a.user_id AND i.status='settled' JOIN expert_onboarding_payment_facts f ON f.invoice_id=i.id AND f.admission='interview' WHERE a.id=NEW.application_id AND a.user_id=NEW.user_id) THEN RAISE EXCEPTION 'expert_application_promo_owner' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='expert_application_promo_confirmations' THEN
 IF NOT expert_card_manager_authority_valid(NEW.manager_id,NEW.session_hash) OR NOT EXISTS(SELECT 1 FROM expert_application_promo_proofs p WHERE p.application_id=NEW.application_id AND p.user_id=NEW.user_id) OR NEW.proof_digest IS DISTINCT FROM (SELECT 'sha256:'||encode(digest(coalesce(string_agg(p.id::text||':'||p.kind||':'||p.reference,E'\n' ORDER BY p.created_at,p.id),''),'sha256'),'hex') FROM expert_application_promo_proofs p WHERE p.application_id=NEW.application_id AND p.user_id=NEW.user_id) THEN RAISE EXCEPTION 'expert_application_promo_manager' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_campaign_order_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  quote expert_campaign_quotes%ROWTYPE;
  tariff expert_residency_tariff_versions%ROWTYPE;
  expert experts%ROWTYPE;
  checked_at timestamptz;
BEGIN
  IF NEW.commercial_policy_version <> 'expert_campaign_v1' THEN RETURN NEW; END IF;
  SELECT * INTO quote FROM expert_campaign_quotes WHERE id=NEW.campaign_quote_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514';
  END IF;
  LOCK TABLE consent_document_versions IN SHARE MODE;
  PERFORM pg_advisory_xact_lock(hashtextextended(quote.user_id::text,0));
  IF NOT expert_campaign_current_profile_valid(quote.user_id,quote.id) THEN RAISE EXCEPTION 'expert_offer_current_profile_required' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM users WHERE id=quote.user_id AND active=true FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514'; END IF;
  SELECT * INTO expert FROM experts WHERE id=NEW.expert_id FOR SHARE;
  IF NOT FOUND OR expert.user_id IS DISTINCT FROM quote.user_id OR (
    (quote.rule_version IN('expert_energy_start_v2','expert_separated_sales_v3') OR NOT expert.active OR NOT expert.verified) AND NOT EXISTS(
      SELECT 1 FROM expert_card_main_acceptances a WHERE a.expert_id=NEW.expert_id AND a.user_id=quote.user_id
        AND a.quote_id=quote.id AND a.application_id IS NOT NULL AND a.review_id IS NOT NULL
        AND expert_card_activation_gate_valid(a.user_id,a.review_id)
        AND (a.acceptance_source='explicit' OR a.offer_schedule_id=(SELECT latest.id FROM expert_offer_schedules latest WHERE latest.user_id=quote.user_id ORDER BY latest.created_at DESC,latest.id DESC LIMIT 1)))) THEN
    RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514';
  END IF;
  PERFORM 1 FROM expert_campaign_quotes WHERE id=quote.id FOR SHARE;
  SELECT * INTO tariff FROM expert_residency_tariff_versions WHERE id=quote.tariff_version_id FOR SHARE;
  checked_at := clock_timestamp();
  IF checked_at < quote.quoted_at OR checked_at >= quote.expires_at THEN
    RAISE EXCEPTION 'expert_campaign_order_expired' USING ERRCODE='23514',CONSTRAINT='expert_campaign_order_expired';
  END IF;
  IF NOT FOUND OR tariff.commercial_policy_version <> 'expert_residency_v2'
    OR ((checked_at < tariff.active_from OR checked_at >= tariff.active_to) AND NOT (quote.rule_version='expert_separated_sales_v3' AND EXISTS(SELECT 1 FROM expert_sales_paid_locks l WHERE l.user_id=quote.user_id AND l.invoice_id=quote.paid_lock_invoice_id AND l.selection_id=quote.sales_selection_id)))
    OR NEW.created_at < quote.quoted_at OR NEW.created_at > checked_at
    OR NEW.provider_deadline IS DISTINCT FROM quote.expires_at
    OR NOT isfinite(NEW.created_at) OR NOT isfinite(NEW.payment_deadline)
    OR ROW(NEW.tariff_version_id,NEW.campaign_term_months,NEW.snapshot_display_name,NEW.price_minor,NEW.currency,
      NEW.duration_seconds,NEW.credit_cap_bps,NEW.individual_services_enabled,NEW.group_event_limit,NEW.statistics_level,NEW.support_priority)
      IS DISTINCT FROM ROW(quote.tariff_version_id,quote.term_months,quote.display_name,quote.price_minor,quote.currency,
      quote.duration_seconds,quote.credit_cap_bps,quote.individual_services_enabled,quote.group_event_limit,quote.statistics_level,quote.support_priority)
  THEN RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_campaign_quote_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  tariff expert_residency_tariff_versions%ROWTYPE;
  stage_end timestamptz;
  expected_expiry timestamptz;
BEGIN
  LOCK TABLE consent_document_versions IN SHARE MODE;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
  PERFORM 1 FROM users WHERE id=NEW.user_id AND active=true FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expert_campaign_source_invalid' USING ERRCODE='23514';
  END IF;
  SELECT * INTO tariff FROM expert_residency_tariff_versions WHERE id=NEW.tariff_version_id FOR SHARE;
  IF NOT FOUND OR tariff.commercial_policy_version <> 'expert_residency_v2'
    OR NOT isfinite(NEW.quoted_at) OR NEW.quoted_at < tariff.active_from OR NEW.quoted_at >= tariff.active_to
    OR ROW(NEW.base_monthly_minor,NEW.currency,NEW.display_name,NEW.credit_cap_bps,
      NEW.individual_services_enabled,NEW.group_event_limit,NEW.statistics_level,NEW.support_priority)
      IS DISTINCT FROM ROW(tariff.price_minor,tariff.currency,tariff.display_name,tariff.credit_cap_bps,
      tariff.individual_services_enabled,tariff.group_event_limit,tariff.statistics_level,tariff.support_priority)
    OR tariff.duration_seconds <> 2592000 THEN
    RAISE EXCEPTION 'expert_campaign_source_invalid' USING ERRCODE='23514';
  END IF;
  stage_end := CASE
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '72 hours' THEN NEW.calculation_timestamp + interval '72 hours'
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '144 hours' THEN NEW.calculation_timestamp + interval '144 hours'
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '216 hours' THEN NEW.calculation_timestamp + interval '216 hours'
    ELSE 'infinity'::timestamptz END;
  expected_expiry := least(NEW.quoted_at + interval '15 minutes',date_trunc('milliseconds',tariff.active_to),stage_end);
  IF NEW.expires_at IS DISTINCT FROM expected_expiry THEN
    RAISE EXCEPTION 'expert_campaign_expiry_invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_offer_manager_fact()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT expert_card_manager_authority_valid(NEW.manager_id,NEW.session_hash) THEN RAISE EXCEPTION 'expert_offer_manager_required' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='expert_offer_profile_verifications' THEN
 IF NEW.profile_revision IS DISTINCT FROM (SELECT max(revision) FROM expert_offer_profiles WHERE user_id=NEW.user_id) THEN RAISE EXCEPTION 'expert_offer_current_profile_required' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_offer_schedule_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 NEW.application_audit_id:=NEW.application_id; NEW.review_audit_id:=NEW.review_id;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM expert_card_main_acceptances a JOIN expert_campaign_quotes q ON q.id=a.quote_id JOIN expert_card_drafts d ON d.application_id=a.application_id AND d.user_id=a.user_id JOIN expert_card_requests req ON req.bot_id=NEW.bot_id AND req.bot_id||':'||req.update_id=NEW.source_update_id AND req.user_id=NEW.user_id AND req.operation='main_accept' AND req.result_id=NEW.original_acceptance_id AND req.erased_at IS NULL
 WHERE NEW.created_at>=a.created_at AND NEW.created_at<=clock_timestamp() AND a.id=NEW.original_acceptance_id AND a.acceptance_source='explicit' AND a.user_id=NEW.user_id AND a.application_id=NEW.application_id AND a.expert_id=NEW.expert_id AND a.review_id=NEW.review_id AND a.revision=NEW.revision AND a.public_digest=NEW.public_digest AND q.id=NEW.original_quote_id AND q.tariff_version_id=NEW.tariff_version_id AND q.term_months=NEW.term_months AND q.profile_revision=NEW.profile_revision AND q.rule_version='expert_energy_start_v2' AND NEW.consent_version=d.messaging_policy_version AND NEW.bot_id=d.work_bot_id AND NEW.bot_key=d.work_bot_key AND NEW.chat_id=d.work_chat_id AND NEW.request_key=NEW.source_update_id AND NEW.request_digest=req.request_digest AND expert_card_activation_gate_valid(a.user_id,a.review_id)) THEN RAISE EXCEPTION 'expert_offer_schedule_source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_offer_subject_cleanup()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='users' THEN
  PERFORM clear_expert_offer_delivery_state(NEW.id);
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='consents' THEN
  PERFORM clear_expert_offer_delivery_state(NEW.user_id);
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
  PERFORM clear_expert_offer_delivery_state(OLD.user_id);
  RETURN OLD;
 END IF;
 IF NEW.status<>'active' OR NEW.user_id IS DISTINCT FROM OLD.user_id OR ROW(NEW.provider,NEW.bot_key,NEW.external_id,NEW.external_chat_id) IS DISTINCT FROM ROW(OLD.provider,OLD.bot_key,OLD.external_id,OLD.external_chat_id) THEN
  PERFORM clear_expert_offer_delivery_state(OLD.user_id);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_offer_v2_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t expert_residency_tariff_versions%ROWTYPE; p expert_offer_profiles%ROWTYPE; stage_end timestamptz; earliest timestamptz;
BEGIN
 LOCK TABLE consent_document_versions IN SHARE MODE;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
 PERFORM 1 FROM users WHERE id=NEW.user_id AND active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'expert_offer_owner_invalid' USING ERRCODE='23514'; END IF;
 SELECT * INTO p FROM expert_offer_profiles WHERE user_id=NEW.user_id AND revision=NEW.profile_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'expert_offer_profile_invalid' USING ERRCODE='23514'; END IF;
 SELECT * INTO t FROM expert_residency_tariff_versions WHERE id=NEW.tariff_version_id FOR SHARE;
 IF NOT FOUND OR t.commercial_policy_version<>'expert_residency_v2' OR t.duration_seconds<>2592000 OR NEW.quoted_at<t.active_from OR NEW.quoted_at>=t.active_to
 OR ROW(NEW.base_monthly_minor,NEW.currency,NEW.display_name,NEW.credit_cap_bps,NEW.individual_services_enabled,NEW.group_event_limit,NEW.statistics_level,NEW.support_priority)
 IS DISTINCT FROM ROW(t.price_minor+CASE WHEN p.million_city THEN 500000 ELSE 0 END+CASE WHEN p.service_format='online_only' THEN 300000 ELSE 0 END-CASE WHEN p.ticket_minor<300000 THEN 100000 ELSE 0 END,t.currency,t.display_name,t.credit_cap_bps,t.individual_services_enabled,t.group_event_limit,t.statistics_level,t.support_priority)
 THEN RAISE EXCEPTION 'expert_offer_tariff_invalid' USING ERRCODE='23514'; END IF;
 IF p.participant_kind='space' AND NOT EXISTS(SELECT 1 FROM expert_space_tariff_approvals WHERE tariff_version_id=NEW.tariff_version_id) THEN RAISE EXCEPTION 'expert_space_tariff_unapproved' USING ERRCODE='23514'; END IF;
 IF NEW.start_discount_bps IS DISTINCT FROM (CASE WHEN NEW.quoted_at-NEW.calculation_timestamp>=interval '168 hours' THEN 0 WHEN p.participant_kind='space' THEN 1000 WHEN NEW.quoted_at-NEW.calculation_timestamp<interval '96 hours' THEN 1500 ELSE 1000 END) THEN RAISE EXCEPTION 'expert_offer_package_invalid' USING ERRCODE='23514'; END IF;
 SELECT min(calculation_timestamp) INTO earliest FROM expert_campaign_anchors WHERE user_id=NEW.user_id;
 IF NEW.calculation_timestamp IS DISTINCT FROM earliest THEN RAISE EXCEPTION 'expert_offer_anchor_invalid' USING ERRCODE='23514'; END IF;
 stage_end:=CASE WHEN NEW.quoted_at-NEW.calculation_timestamp<interval '96 hours' THEN NEW.calculation_timestamp+interval '96 hours' WHEN NEW.quoted_at-NEW.calculation_timestamp<interval '168 hours' THEN NEW.calculation_timestamp+interval '168 hours' WHEN NEW.quoted_at-NEW.calculation_timestamp<interval '240 hours' THEN NEW.calculation_timestamp+interval '240 hours' ELSE NEW.quoted_at+interval '24 hours' END;
 IF NEW.expires_at IS DISTINCT FROM least(stage_end,date_trunc('milliseconds',t.active_to)) THEN RAISE EXCEPTION 'expert_offer_expiry_invalid' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_referral_admin_approval_global_unique()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE lock_key bigint;
BEGIN
  FOR lock_key IN SELECT DISTINCT hashtextextended(value::text, 928451) AS advisory_key FROM unnest(array[NEW.approval_id,NEW.second_approval_id]) AS approvals(value) WHERE value is not null ORDER BY advisory_key LOOP
    PERFORM pg_advisory_xact_lock(lock_key);
  END LOOP;
  IF EXISTS (SELECT 1 FROM expert_referral_admin_execution_results existing WHERE existing.approval_id in (NEW.approval_id,NEW.second_approval_id) OR existing.second_approval_id in (NEW.approval_id,NEW.second_approval_id)) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='expert_referral_admin_approval_global_unique';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.erase_expert_sales_subject(subject uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(subject::text,0));
 IF NOT EXISTS(SELECT 1 FROM expert_sales_bases WHERE user_id=subject) THEN RETURN; END IF;
 INSERT INTO expert_sales_erased_cohorts(user_id) VALUES(subject) ON CONFLICT DO NOTHING;
 UPDATE expert_sales_bases SET bot_id=NULL,bot_key=NULL,chat_id=NULL,consent_version=NULL WHERE user_id=subject;
 UPDATE expert_sales_choices SET request_key=NULL,request_digest=NULL WHERE user_id=subject;
 UPDATE expert_sales_provider_requests r SET encrypted_body=NULL,key_reference=NULL,status=CASE WHEN status='prepared' THEN 'cancelled' ELSE status END FROM expert_sales_fee_attempts a WHERE a.invoice_id=r.invoice_id AND a.user_id=subject;
 UPDATE expert_sales_notices n SET status='cancelled',receipt=NULL FROM expert_sales_bases b WHERE b.id=n.base_id AND b.user_id=subject;
 -- Uninvoiced sales with no issued quote can be removed completely; the opaque
 -- tombstone prevents a later consent grant from resetting the campaign clock.
 IF NOT EXISTS(SELECT 1 FROM expert_campaign_quotes WHERE user_id=subject) AND NOT EXISTS(SELECT 1 FROM expert_onboarding_invoices WHERE user_id=subject) THEN
  DELETE FROM expert_sales_ticks WHERE base_id IN(SELECT id FROM expert_sales_bases WHERE user_id=subject);
  DELETE FROM expert_sales_notices WHERE base_id IN(SELECT id FROM expert_sales_bases WHERE user_id=subject);
  DELETE FROM expert_sales_selections WHERE user_id=subject;
  DELETE FROM expert_sales_choices WHERE user_id=subject;
  DELETE FROM expert_sales_bases WHERE user_id=subject;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.erase_resident_verification_subject(subject uuid)
