END $function$

CREATE OR REPLACE FUNCTION public.expert_card_activation_gate_valid(target_user uuid, target_review uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE v resident_card_versions; d expert_card_drafts; a jsonb;
BEGIN
 SELECT * INTO v FROM resident_card_versions WHERE review_id=target_review;
 IF NOT FOUND THEN RETURN expert_card_legacy_activation_gate(target_user,target_review); END IF;
 SELECT * INTO d FROM expert_card_drafts WHERE id=v.draft_id AND user_id=target_user;
 IF NOT FOUND OR NOT expert_card_current_messaging_authority(target_user,d.messaging_policy_version) OR NOT EXISTS(SELECT 1 FROM users WHERE id=target_user AND active) OR NOT EXISTS(SELECT 1 FROM channel_identities WHERE user_id=target_user AND provider='telegram' AND bot_key=d.work_bot_key AND external_id=d.work_chat_id AND external_chat_id=d.work_chat_id AND status='active') THEN RETURN false; END IF;
 a:=resident_safety_assess(v.safety_fields,v.revision);
 IF (a->>'blocked')::boolean OR a IS DISTINCT FROM v.safety_proof THEN RETURN false; END IF;
 -- Paid acquisition proof is historical and immutable. Updating content never creates another charge/campaign.
 IF EXISTS(SELECT 1 FROM experts_published p JOIN expert_card_main_orders m ON m.order_id=p.paid_order_id AND m.user_id=p.user_id JOIN expert_main_activation_admissions admission ON admission.order_id=m.order_id AND admission.review_audit_id=m.review_audit_id AND admission.public_digest=m.public_digest WHERE p.draft_id=d.id AND p.user_id=target_user) THEN RETURN true; END IF;
 RETURN EXISTS(SELECT 1 FROM expert_onboarding_applications ap JOIN expert_onboarding_invoices i ON i.application_id=ap.id AND i.status='settled' JOIN expert_onboarding_payment_facts f ON f.invoice_id=i.id AND f.admission='interview' WHERE ap.id=d.application_id AND ap.user_id=target_user AND ap.verification_status='approved' AND ap.archived_at IS NULL AND ap.archive_until_date IS NULL)
 AND (EXISTS(SELECT 1 FROM expert_card_material_jobs j JOIN expert_card_material_templates t ON t.id=j.template_id AND t.content_version=j.content_version AND t.status='approved' WHERE j.review_id=target_review AND j.status='delivered' AND j.delivery_receipt IS NOT NULL AND j.user_id=target_user) OR EXISTS(SELECT 1 FROM expert_application_material_jobs j JOIN expert_card_material_templates t ON t.id=j.template_id AND t.content_version=j.content_version AND t.status='approved' WHERE j.application_id=d.application_id AND j.user_id=target_user AND j.status='delivered' AND j.delivery_receipt IS NOT NULL))
 AND EXISTS(SELECT 1 FROM expert_application_promo_confirmations p WHERE p.application_id=d.application_id AND p.user_id=target_user AND p.proof_digest=(SELECT 'sha256:'||encode(digest(coalesce(string_agg(id::text||':'||kind||':'||reference,E'\n' ORDER BY created_at,id),''),'sha256'),'hex') FROM expert_application_promo_proofs WHERE application_id=d.application_id AND user_id=target_user))
 AND EXISTS(SELECT 1 FROM expert_application_promo_proofs WHERE application_id=d.application_id AND user_id=target_user);
END $function$

CREATE OR REPLACE FUNCTION public.expert_card_legacy_activation_gate(target_user uuid, target_review uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE r record; assessment jsonb;
BEGIN
 IF target_review IS NULL THEN RETURN false; END IF;
 SELECT * INTO r FROM expert_card_reviews WHERE id=target_review AND user_id=target_user AND action='approve';
 IF NOT FOUND OR r.safety_proof IS NULL THEN RETURN false; END IF;
 assessment:=resident_safety_assess(resident_card_effective_fields(r.draft_id),r.revision);
 IF (assessment->>'blocked')::boolean OR r.safety_proof IS DISTINCT FROM assessment THEN RETURN false; END IF;
 RETURN expert_card_activation_gate_before_safety(target_user,target_review);
END $function$

CREATE OR REPLACE FUNCTION public.expert_card_tag_selection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM expert_card_drafts WHERE id=NEW.draft_id AND user_id=NEW.user_id AND status IN ('collecting','changes_requested') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'card_tag_draft_unavailable'; END IF;
 PERFORM 1 FROM hashtags_db WHERE id=NEW.tag_id AND is_active FOR SHARE;
 IF NOT FOUND OR (SELECT count(*) FROM expert_card_draft_tags WHERE draft_id=NEW.draft_id)>=20 THEN RAISE EXCEPTION 'card_tag_selection_invalid'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.expert_first_settlement_guard_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_first_settlement_transition', MESSAGE='expert_first_settlement_guard';
  END IF;
  IF NOT (
      (OLD.eligibility = 'pending_feature_hold' AND NEW.eligibility IN ('eligible','permanently_ineligible','cancelled_by_refund'))
      OR (OLD.eligibility = 'eligible' AND NEW.eligibility = 'cancelled_by_refund')
    )
    OR ROW(NEW.id,NEW.expert_id,NEW.settlement_sequence,NEW.qualifying_order_id,NEW.qualifying_payment_attempt_id,NEW.referral_id,NEW.settlement_expert_active,NEW.settlement_expert_verified,NEW.settlement_abuse_cleared,NEW.settlement_control_version,NEW.settlement_invitee_user_id,NEW.settlement_invitee_channel_identity_id,NEW.settlement_inviter_expert_id,NEW.settlement_inviter_user_id,NEW.settlement_inviter_channel_identity_id,NEW.settled_at,NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.id,OLD.expert_id,OLD.settlement_sequence,OLD.qualifying_order_id,OLD.qualifying_payment_attempt_id,OLD.referral_id,OLD.settlement_expert_active,OLD.settlement_expert_verified,OLD.settlement_abuse_cleared,OLD.settlement_control_version,OLD.settlement_invitee_user_id,OLD.settlement_invitee_channel_identity_id,OLD.settlement_inviter_expert_id,OLD.settlement_inviter_user_id,OLD.settlement_inviter_channel_identity_id,OLD.settled_at,OLD.created_at)
  THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_first_settlement_transition', MESSAGE='expert_first_settlement_guard';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expert_provider_reversal_result_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='INSERT' AND NEW.result_legacy_exempt THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_legacy_exempt_forbidden', MESSAGE='expert_provider_reversal_legacy_exempt_forbidden';
  END IF;
  IF TG_OP='UPDATE' AND NEW.result_legacy_exempt AND NOT OLD.result_legacy_exempt THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_legacy_exempt_forbidden', MESSAGE='expert_provider_reversal_legacy_exempt_forbidden';
  END IF;
  IF TG_OP='INSERT' THEN
    RETURN NEW;
  END IF;
  IF OLD.status='processed' AND OLD.event_kind IN ('refunded','charged_back')
     AND (NEW.result_payload IS DISTINCT FROM OLD.result_payload OR NEW.result_schema_version IS DISTINCT FROM OLD.result_schema_version OR NEW.result_legacy_exempt IS DISTINCT FROM OLD.result_legacy_exempt)
  THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_provider_reversal_result_immutable', MESSAGE='expert_provider_reversal_result_immutable';
  END IF;
  IF NEW.status='processed' AND NEW.event_kind IN ('refunded','charged_back')
     AND OLD.status IS DISTINCT FROM 'processed' AND (NEW.result_schema_version IS DISTINCT FROM 1 OR NEW.result_legacy_exempt)
  THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_result_required', MESSAGE='expert_provider_reversal_result_required';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expert_referral_maturities_append_only_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status IN ('granted', 'cancelled') THEN RAISE EXCEPTION 'expert_referral_maturities_terminal_immutable' USING ERRCODE = '23514'; END IF;
  IF NEW.status IN ('granted', 'cancelled') AND (NEW.settled_at <> OLD.settled_at OR NEW.matures_at <> OLD.matures_at OR NEW.first_settlement_id <> OLD.first_settlement_id OR NEW.referral_id <> OLD.referral_id OR NEW.qualifying_order_id <> OLD.qualifying_order_id OR NEW.qualifying_payment_attempt_id <> OLD.qualifying_payment_attempt_id OR NEW.inviter_expert_id <> OLD.inviter_expert_id) THEN
    RAISE EXCEPTION 'expert_referral_maturities_financial_facts_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.expert_referral_validate_ledger_allocation_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_entry_id uuid;
  expected_total bigint;
  allocated_total bigint;
BEGIN
  IF TG_TABLE_NAME = 'expert_referral_ledger_entries' THEN
    target_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  ELSE
    target_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.ledger_entry_id ELSE NEW.ledger_entry_id END;
  END IF;

  SELECT amount_minor
    INTO expected_total
    FROM expert_referral_ledger_entries
    WHERE id = target_entry_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT coalesce(sum(amount_minor), 0)::bigint
    INTO allocated_total
    FROM expert_referral_ledger_allocations
    WHERE ledger_entry_id = target_entry_id;

  IF allocated_total <> expected_total THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'expert_ledger_allocations_exact_total',
      MESSAGE = 'expert_ledger_allocations_exact_total';
  END IF;

  RETURN NULL;
END;
$function$

