CREATE OR REPLACE FUNCTION public.resident_verification_followup_valid(a jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$ BEGIN
 IF a IS NULL OR jsonb_typeof(a)<>'object' OR octet_length(a::text)>100000 OR NOT(a ? 'answer' OR a ? 'documents') OR EXISTS(SELECT 1 FROM jsonb_object_keys(a) key WHERE key NOT IN('answer','documents')) THEN RETURN false; END IF;
 IF a ? 'answer' AND (jsonb_typeof(a->'answer')<>'string' OR length(btrim(a->>'answer',E' \t\r\n')) NOT BETWEEN 1 AND 3000 OR a->>'answer' ~ U&'[\0001-\0008\000B-\001F\007F-\009F]') THEN RETURN false; END IF;
 IF a ? 'documents' AND (jsonb_typeof(a->'documents')<>'array' OR jsonb_array_length(a->'documents') NOT BETWEEN 1 AND 10 OR NOT resident_verification_draft_v2_valid(jsonb_build_object('education',a->'documents'))) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.resident_verification_price_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
 IF NEW.rule_version='expert_separated_sales_v3' AND EXISTS(SELECT 1 FROM expert_sales_bases b WHERE b.user_id=NEW.user_id AND b.base_offer_shown_at=NEW.calculation_timestamp) THEN RETURN NEW; END IF;
 IF NOT resident_verification_price_allowed(NEW.user_id) THEN RAISE EXCEPTION 'resident_verification_required'; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.resident_verification_stage_projection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP='DELETE' THEN UPDATE users SET current_verification_stage=coalesce((SELECT progress FROM residents_applications WHERE user_id=OLD.user_id AND is_current),'NONE') WHERE id=OLD.user_id; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.submitted_at IS NULL AND NEW.submitted_at IS NOT NULL THEN
 INSERT INTO resident_verification_check_work(application_id,user_id,submitted_revision) VALUES(NEW.id,NEW.user_id,NEW.submitted_revision);
 INSERT INTO resident_check_generations(application_id,generation,submitted_revision,supplement_revision) VALUES(NEW.id,1,NEW.submitted_revision,NEW.revision);
 END IF;
 IF NEW.is_current THEN UPDATE users SET current_verification_stage=NEW.progress WHERE id=NEW.user_id; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.resident_verification_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM channel_identities ci JOIN users u ON u.id=ci.user_id AND u.active WHERE ci.id=NEW.channel_identity_id AND ci.user_id=NEW.user_id AND ci.provider='telegram' AND ci.status='active' AND ci.bot_key=NEW.bot_key AND ci.external_id=NEW.telegram_user_id AND ci.external_chat_id=NEW.chat_id) THEN RAISE EXCEPTION 'resident_identity_unavailable'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'PENDING_DOCS' OR NEW.progress<>'FORM_FILLING' OR NEW.revision<>0 OR NEW.submitted_at IS NOT NULL OR NOT NEW.is_current THEN RAISE EXCEPTION 'resident_initial_state_invalid'; END IF;
  IF NEW.attempt_number>1 AND (NOT EXISTS(SELECT 1 FROM residents_applications previous_form JOIN resident_review_events e ON e.attempt_id=previous_form.id AND e.action='REJECT_SOFT' AND resident_reapply_eligible(e.reapply_at,clock_timestamp()) WHERE previous_form.user_id=NEW.user_id AND previous_form.attempt_number=NEW.attempt_number-1 AND NOT previous_form.is_current AND previous_form.status='REJECTED') OR EXISTS(SELECT 1 FROM expert_onboarding_payment_facts WHERE user_id=NEW.user_id) OR EXISTS(SELECT 1 FROM expert_sales_paid_locks WHERE user_id=NEW.user_id)) THEN RAISE EXCEPTION 'resident_reapply_unavailable'; END IF;
  NEW.created_at:=clock_timestamp();
  INSERT INTO resident_verification_cohorts(user_id) VALUES(NEW.user_id) ON CONFLICT DO NOTHING;
 ELSE
  IF ROW(OLD.user_id,OLD.bot_id,OLD.bot_key,OLD.channel_identity_id,OLD.created_at,OLD.policy_version,OLD.education_requirement,OLD.telegram_user_id,OLD.chat_id,OLD.form_version,OLD.attempt_number) IS DISTINCT FROM ROW(NEW.user_id,NEW.bot_id,NEW.bot_key,NEW.channel_identity_id,NEW.created_at,NEW.policy_version,NEW.education_requirement,NEW.telegram_user_id,NEW.chat_id,NEW.form_version,NEW.attempt_number) OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'resident_revision_invalid'; END IF;
  IF NOT OLD.is_current OR (OLD.is_current AND NOT NEW.is_current AND (OLD.status<>'REJECTED' OR NOT EXISTS(SELECT 1 FROM resident_review_events WHERE attempt_id=OLD.id AND action='REJECT_SOFT' AND resident_reapply_eligible(reapply_at,clock_timestamp())))) THEN RAISE EXCEPTION 'resident_attempt_frozen'; END IF;
  IF OLD.submitted_at IS NOT NULL AND ROW(OLD.draft,OLD.submitted_draft,OLD.submitted_at,OLD.submitted_revision) IS DISTINCT FROM ROW(NEW.draft,NEW.submitted_draft,NEW.submitted_at,NEW.submitted_revision) THEN RAISE EXCEPTION 'resident_submission_frozen'; END IF;
  IF OLD.submitted_at IS NOT NULL AND NEW.check_generation<>OLD.check_generation AND (NEW.check_generation<>OLD.check_generation+1 OR NOT EXISTS(SELECT 1 FROM resident_check_generations g JOIN resident_information_requests r ON r.id=g.request_id WHERE g.application_id=OLD.id AND g.generation=NEW.check_generation AND r.id=OLD.active_request_id AND r.status IN('completed','timeout'))) THEN RAISE EXCEPTION 'resident_check_generation_source'; END IF;
  IF OLD.status<>NEW.status THEN
   IF NEW.status IN('APPROVED_BASIC','APPROVED_EXCLUSIVE','REJECTED','INFO_REQUESTED') AND NOT EXISTS(SELECT 1 FROM resident_review_events e WHERE e.attempt_id=OLD.id AND e.source_revision=OLD.revision AND e.source_generation=OLD.check_generation AND (e.action=NEW.status OR (NEW.status='REJECTED' AND e.action IN('REJECT_SOFT','REJECT_HARD')))) THEN RAISE EXCEPTION 'resident_manager_decisions_unavailable'; END IF;
   IF NEW.status='UNDER_REVIEW' AND OLD.status<>'PENDING_DOCS' AND (OLD.status<>'INFO_REQUESTED' OR NOT EXISTS(SELECT 1 FROM resident_information_requests WHERE id=OLD.active_request_id AND application_id=OLD.id AND status IN('completed','timeout'))) THEN RAISE EXCEPTION 'resident_review_source'; END IF;
  END IF;
  IF OLD.submitted_at IS NULL AND NEW.submitted_at IS NOT NULL THEN NEW.submitted_at:=clock_timestamp(); NEW.submitted_revision:=NEW.revision; NEW.check_generation:=1; END IF;
 END IF;
 IF NEW.submitted_at IS NOT NULL AND NEW.draft<>NEW.submitted_draft THEN RAISE EXCEPTION 'resident_submission_invalid'; END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_and_consume_selarti_budget_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE approval admin_approvals%ROWTYPE; expected_hash text;
BEGIN
  PERFORM pg_advisory_xact_lock(739184, 42036);
  expected_hash := 'sha256:' || encode(digest(convert_to(to_json(concat_ws('|','selarti-budget-policy-v1',NEW.version,NEW.status,to_char(NEW.effective_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),coalesce(to_char(NEW.effective_to at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'-'),NEW.global_cap_rub_minor,NEW.global_warning_rub_minor,NEW.global_soft_rub_minor,NEW.per_user_warning_rub_minor,NEW.per_user_soft_rub_minor,NEW.per_user_hard_rub_minor,NEW.official_usd_rub_quote_micros,NEW.selarti_uplift_bps,NEW.usd_micros_per_request,NEW.usd_micros_per_unit,NEW.worst_case_billable_units,NEW.rate_version,NEW.model_version,NEW.stress_inflation_bps))::text,'UTF8'),'sha256'),'hex');
  SELECT * INTO approval FROM admin_approvals WHERE id=NEW.approval_id FOR UPDATE;
  IF approval.id IS NULL OR approval.action<>'selarti_budget.policy_approve' OR approval.object_type<>'selarti_budget_policy' OR approval.object_id<>NEW.id OR approval.required_role<>'security_admin' OR approval.requester_id=approval.approver_id OR approval.approver_id IS NULL OR approval.requester_session_id_hash IS NULL OR approval.requester_mfa_verified_at IS NULL OR approval.approver_session_id_hash IS NULL OR approval.approver_mfa_verified_at IS NULL OR approval.approved_at IS NULL OR approval.approved_at>NEW.created_at OR approval.consumed_at IS NOT NULL OR approval.expires_at<=NEW.created_at OR approval.payload_hash<>expected_hash OR approval.requester_mfa_verified_at < NEW.created_at - interval '15 minutes' OR approval.requester_mfa_verified_at > NEW.created_at OR approval.approver_mfa_verified_at < NEW.created_at - interval '15 minutes' OR approval.approver_mfa_verified_at > NEW.created_at OR NOT EXISTS (SELECT 1 FROM admin_sessions s JOIN admin_role_assignments r ON r.admin_id=s.admin_id AND r.role='security_admin' WHERE s.session_id_hash=approval.requester_session_id_hash AND s.admin_id=approval.requester_id AND s.mfa_verified_at=approval.requester_mfa_verified_at AND s.revoked_at IS NULL AND s.expires_at>NEW.created_at) OR NOT EXISTS (SELECT 1 FROM admin_sessions s JOIN admin_role_assignments r ON r.admin_id=s.admin_id AND r.role='security_admin' WHERE s.session_id_hash=approval.approver_session_id_hash AND s.admin_id=approval.approver_id AND s.mfa_verified_at=approval.approver_mfa_verified_at AND s.revoked_at IS NULL AND s.expires_at>NEW.created_at) THEN RAISE EXCEPTION 'selarti budget approval invalid'; END IF;
  UPDATE admin_approvals SET consumed_at=NEW.created_at WHERE id=NEW.approval_id;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_campaign_prompt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status='active' and not exists (
    select 1 from test_expert_prompt_assets p where p.id=new.prompt_asset_id and p.version=new.prompt_asset_version
      and p.status='approved' and p.official_contract_evidence is not null
  ) then raise exception 'test expert campaign prompt is not approved'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_campaign_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='DELETE' then raise exception 'test expert immutable fact'; end if;
  if (old.id,old.code,old.version,old.cap_units,old.provider_calls_per_message,old.prompt_asset_id,old.prompt_asset_version,old.effective_from,old.effective_to,old.created_at)
     is distinct from (new.id,new.code,new.version,new.cap_units,new.provider_calls_per_message,new.prompt_asset_id,new.prompt_asset_version,new.effective_from,new.effective_to,new.created_at)
     or not ((old.status='inactive' and new.status='active') or (old.status='active' and new.status='retired'))
  then raise exception 'invalid test expert campaign transition'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_prompt_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='DELETE' then raise exception 'test expert immutable fact'; end if;
  if (old.id,old.asset_key,old.version,old.sha256,old.source_path,old.official_contract_evidence,old.created_at)
     is distinct from (new.id,new.asset_key,new.version,new.sha256,new.source_path,new.official_contract_evidence,new.created_at)
     or not ((old.status='inactive' and new.status='approved') or (old.status='approved' and new.status='retired'))
  then raise exception 'invalid test expert prompt transition'; end if;
  return new;
end $function$
